export const researchDate = '2026-09-07';
export const premise = 'Build a 10GbE FPGA packet-processing endpoint that receives synthetic quote updates, maintains bounded symbol state, evaluates an integer-scaled rule, enforces admission and outstanding-order limits, and returns simulated order intents. Own the RTL, tests, constraints, host tools, and measurements.';
export const limitations = 'This is an architecture and learning plan, not a proven implementation or a guarantee of employment. The inspected project contains a Python generator and an unfinished decoder interface. No RTL regression, FPGA build, line-rate test, or latency result was established in this audit. Estimates assume one beginner working 8-10 hours per week; hardware access and debugging can extend the project to 12-18 months.';

