export const phases = [
 {id:'p1',weeks:'1-2',hours:20,title:'One packet, one trustworthy result',deliverable:'A registered 248-bit decoder with an independent cocotb scoreboard.',learn:'Packed vectors, byte order, clock edges, nonblocking assignments, reset polarity, and simulator scheduling.',build:['Write protocol_v1.md: 31 bytes, MSB-first packed vector, unsigned integers, price scale 10,000.','Finish market_data_decoder.sv; add decode_error and endmodule. Keep synchronous active-low rst_n for this first block.','Refactor gen_packet.py into importable pack/unpack helpers and a CLI; add independently calculated fixtures.','Create a cocotb runner, pinned environment, and a short README with one reproducible test command.'],gate:'Known vector, each field boundary, idle, reset, rejected input, and consecutive packets pass. Save a waveform and record the simulator versions.',challenge:'Predict the next five output cycles on paper before simulation. Deliberately swap bid/ask slices and make the scoreboard catch it.',sources:['timingmodel','cocotb','verilator'],depends:'No earlier milestone. Audit board availability/licensing in parallel.'},
 {id:'p2',weeks:'3-4',hours:20,title:'Turn the packet into a stream',deliverable:'A 64-bit ready/valid interface and a bounded 31-byte assembler.',learn:'Accepted beats, TKEEP/TLAST, latency versus throughput, FIFO occupancy, basic synthesis.',build:['Define byte lane 0 as tdata[7:0], carrying the first wire byte. Map bytes explicitly into the MSB-first packed decoder input.','Implement axis_quote_assembler and an elastic buffer; legal final keep is 0x7F after three full 8-byte beats.','Add mid-packet stalls, final-beat stalls, length errors, reset, and no-loss/no-duplication scoreboards.','Run a first small synthesis with a real clock constraint and inspect inferred registers.'],gate:'No state advances without valid && ready. All output qualifiers remain stable under stalls. Truncated and oversized messages never become accepted quotes.',challenge:'The stall puzzle: stop the receiver on the final beat, then resume without losing or duplicating a packet.',sources:['axis','tcl','networklearn'],depends:'p1'},
 {id:'p3',weeks:'5-8',hours:40,title:'Remember state and respect sequence',deliverable:'A bounded quote table, stream health state, and integer-scaled decision pipeline.',learn:'BRAM timing, read-after-write hazards, modular counters, signed widths, fixed-point scaling.',build:['Start with 64 symbol slots; reject unmapped IDs before memory access. Use a valid bit or epoch per entry.','Add stream sequence checking, local receive-time freshness, and explicit resynchronization.','Implement a simple spread/size threshold, then a bounded Q-format coefficient as an optional arithmetic exercise.','On available hardware, bring up the stock image and selected MAC loopback in parallel. Resolve the exact GT clock/pin map.'],gate:'Same-symbol consecutive updates use the newest state; gaps invalidate the stream; arithmetic matches an exact integer model at every boundary.',challenge:'The stale-quote drill: skip a sequence number and prove that no order can escape until state is re-established.',sources:['serial','kriaip','bist','tcl'],depends:'p2; hardware access is a parallel dependency'},
 {id:'p4',weeks:'9-12',hours:40,title:'Close the simulated order loop',deliverable:'Risk admission, outstanding-order accounting, and a C++ simulated venue.',learn:'Atomic reservations, bounded queues, order identity, acknowledgements, fill/cancel races, testing software.',build:['Define OrderIntent-v1 and Feedback-v1 with session epoch, unique ID, side, price, quantity, reason, and correlation ID.','Reserve pending exposure atomically with an output queue slot; release only on validated terminal feedback.','Build C++20 codec/replay/sink tests, Python fault cases, and one focused formal safety check.','Include disarm, kill, timeout, rate limits, feedback reconciliation, and a command/status interface.'],gate:'Two individually legal orders cannot jointly exceed limits. Duplicate feedback cannot free exposure twice. A timeout or ambiguous transmit result disarms the system.',challenge:'The double-order challenge: send two back-to-back orders that would exceed the combined limit and explain the arbitration.',sources:['asan','ubsan','formal'],depends:'p3'},
 {id:'p5',weeks:'13-16',hours:40,title:'Receive real Ethernet frames',deliverable:'Ethernet/IPv4/UDP validation feeding the already-tested quote core.',learn:'MAC versus PCS, network lengths, checksum folding, frame boundaries, packet buffering.',build:['Support an explicit subset: untagged Ethernet, IPv4 IHL=5, no fragments, UDP, configured addresses/ports.','Implement checksum and length checks with a complete-frame commit barrier.','Separate malformed-frame rejection from quote eligibility. Never commit a partial packet.','Use a known MAC model; write tests for every header offset and error path.'],gate:'Bad FCS, bad IP/UDP checksum, inconsistent lengths, truncation, unsupported VLAN/options/fragments, and junk padding have documented outcomes.',challenge:'The last-byte trap: inject an error after an otherwise valid quote and prove zero state changes and zero new orders.',sources:['udp','ipv4','pg210'],depends:'p4'},
 {id:'p6',weeks:'17-20',hours:40,title:'Make the physical link work',deliverable:'A custom UDP request/intent exchange over the candidate 10G link.',learn:'GT lock/reset, reference clocks, CDC constraints, PS-to-PL control, ILA triggers.',build:['Complete board-specific wrappers and constraints; retain reusable IP versions and licenses.','Use the onboard Arm processor for AXI-Lite control/status; keep decisions in programmable logic.','Add a verified CDC boundary only where the selected IP clock architecture requires it.','Capture accepted-frame, state-commit, risk-release, and TX events with matching IDs.'],gate:'Custom packets traverse the board; link loss and reset stop admission; a clean rebuild reproduces the bitstream; ILA traces match simulation.',challenge:'Unplug and reconnect the cable. Re-arm only after link, state, session, and pending-order reconciliation are valid.',sources:['kr260','features','cdc','pg210'],depends:'p5; board, peer, cable, unrestricted stack, and clock mapping required'},
 {id:'p7',weeks:'21-26',hours:60,title:'Break the complete system',deliverable:'An automated fault regression spanning host, RTL, and the board.',learn:'Cross coverage, assertions, randomized clocks/stalls, control races, reproducibility.',build:['Run each module matrix, then pairwise faults such as reset + full queue and kill + feedback.','Add a second simulator for X/reset tests and vendor-model simulation where appropriate.','Exercise AXI-Lite AW/W ordering, strobes, error responses, atomic configuration commits, and counter snapshots.','Use watchdogs, explicit overflow counters, and persistent logs for long runs.'],gate:'Every requirement links to a test or scoped proof and an evidence artifact. No unexplained failure, suppressed warning, or untested critical reject path remains.',challenge:'Fault tournament: a friend selects a hidden seed; you reproduce and diagnose it from the recorded artifacts.',sources:['axis','verilator','formal','tcl'],depends:'p6'},
 {id:'p8',weeks:'27-32',hours:60,title:'Measure, then optimize',deliverable:'Timing closure, throughput sweeps, and latency distributions with defined endpoints.',learn:'Critical paths, queueing, serialization, timestamp uncertainty, coverage interpretation.',build:['Record WNS/TNS, hold/pulse-width results, utilization, DRC/CDC status, and constraints.','Sweep input sizes and burst patterns; calibrate actual traffic offered by the generator.','Collect latency min/median/p99/p99.9/max and sample count; log rejected and missing packets separately.','Build a focused UVM risk-gate bench if ASIC/DV applications are a priority; keep it out of the core critical path.'],gate:'No throughput claim beyond measured load. Internal cycle latency and external latency are separately labeled. Sustained tests include documented duration and loss accounting.',challenge:'Optimize one measured critical path, then show whether area, latency, and timing improved or regressed.',sources:['benchmark','tcl','uvm','xsim'],depends:'p7'},
 {id:'p9',weeks:'33-40',hours:80,title:'Turn engineering into an experiment',deliverable:'A controlled comparison of two integrity-preserving receive architectures.',learn:'Hypotheses, baselines, controlled variables, repeated measurements, related work, limitations.',build:['Baseline A buffers a full frame before parsing. B parses tentatively while receiving but commits only after all checks pass.','Keep hardware, clocks, checks, state capacity, stimulus, and measurement boundaries identical.','Sweep frame sizes and bounded buffer depths; run identical fault regressions for both.','Write a research note with results, raw data, traces, resource costs, and threats to validity.'],gate:'Another person can reproduce the comparison. Improvements are measured and qualified; novelty is assessed against related work with your advisor.',challenge:'Find a workload where the apparently faster architecture loses, and explain why.',sources:['pg210','benchmark','ethernet','taxi'],depends:'p8'},
 {id:'p10',weeks:'41-46',hours:60,title:'Choose one advanced extension',deliverable:'One completed extension selected from the remaining evidence gap.',learn:'Variable-length parsing, real protocol semantics, or stronger formal/DV techniques.',build:['HFT option: MoldUDP64 framing plus a declared ITCH decode subset; add an order book only with lifecycle/recovery completeness.','Networking option: support one VLAN tag and a justified burst-buffer architecture with formal invariants.','Verification option: close one UVM environment and prove bounded FIFO/risk properties with reviewed assumptions.','Select one option; revisit the time budget before adding another.'],gate:'The extension has its own support matrix, reject policy, tests, and measured integration results. Core regression still passes.',challenge:'Demonstrate the exact unsupported input boundary and the safe response to it.',sources:['mold','itch','formal','uvm'],depends:'p9'},
 {id:'p11',weeks:'47-52',hours:60,title:'Reproduce and present',deliverable:'A clean public repository, short hardware demo, and defensible project write-up.',learn:'Technical communication, ownership, experiment reproducibility, interview explanation.',build:['Rebuild from a clean checkout and pinned versions; include license notices and public synthetic fixtures.','Record a 3-minute demo: packet in, state, decision, fault rejection, measurement.','Prepare a block diagram, five waveforms, timing/CDC reports, and a concise bug diary.','Use six weeks as integration and schedule buffer too; preserve quality if an optional extension is unfinished.'],gate:'Every resume claim points to a committed result. Another person can run the simulation without private files. Hardware setup and measurement limitations are explicit.',challenge:'Explain the system at 30-second, 3-minute, and 15-minute depths, including one bug you found yourself.',sources:['hrt','optiver','imc'],depends:'p8; optional phases may be reduced if hardware slips'},
];

export type ModuleSpec = {id:string;name:string;language:string;phase:string;role:string;contract:string;cases:string[];evidence:string;refs:string[]};
export const modules:ModuleSpec[] = [
 {id:'D01',name:'market_data_decoder.sv',language:'SystemVerilog',phase:'1-2',role:'Extract the eight fields from the synthetic packed quote.',contract:'A synchronous active-low reset clears outputs and flags. At each rising edge, an input marked valid is accepted or rejected. Output data changes after that edge. The next block samples it on the next edge. Consecutive accepted inputs may keep decoded_valid high across consecutive cycles; no forced bubble.',cases:['Known 248-bit vector and leading zeros','Every field minimum and maximum, separating encoding validity from quote policy','Unsupported message type; zero size; crossed quote under v1 policy','No input: flags clear and old fields hold','Reset with packet_valid asserted; first packet after reset','Two distinct packets on consecutive edges'],evidence:'Independent scoreboard, exact-cycle assertions, waveform, reset test on a four-state simulator.',refs:['timingmodel']},
 {id:'D02',name:'axis_quote_assembler.sv',language:'SystemVerilog',phase:'3-4',role:'Assemble exactly 31 payload bytes from a 64-bit stream.',contract:'Byte lane 0 is first on the stream. Three beats have keep=0xFF, the fourth keep=0x7F. Advance on handshake only. An invalid length/qualifier enters discard-to-TLAST; a watchdog handles a missing end marker.',cases:['End on every byte offset','30, 31, and 32-byte payloads','Final beat stalled; stalls on every beat','Sparse keep or non-final partial keep','Missing TLAST and reset mid-frame','Back-to-back messages and downstream queue full'],evidence:'Byte-by-byte software reference, timeout tests, stable-under-stall property.',refs:['axis']},
 {id:'D03',name:'axis_elastic_buffer.sv / frame_buffer.sv',language:'SystemVerilog',phase:'3-4 / 13-16',role:'Bound storage and decouple producer/consumer timing.',contract:'Store data and all sideband information together. Occupancy stays in [0, depth]. Complete-frame admission reserves enough capacity or drops the whole frame. An unthrottleable MAC cannot wait indefinitely for TREADY.',cases:['Empty/full transitions; simultaneous push/pop','Pointer wrap at several parameter depths','Reset with queued and partially written frames','Overflow at the first, middle, and last beat','Abort cannot expose a partial frame','Recovery after consecutive rejected frames'],evidence:'FIFO ordering scoreboard, occupancy proof, whole-frame loss accounting.',refs:['axis','formal','pg210']},
 {id:'D04',name:'sequence_health.sv',language:'SystemVerilog',phase:'5-8',role:'Track a single v1 stream and gate stale or unsynchronized state.',contract:'The 32-bit v1 sequence is global to the stream, not per symbol. Track an explicit session epoch. A gap invalidates the stream and disarms decisions. Recovery is an explicit coherent snapshot/restart protocol, never automatic on the next good packet.',cases:['Expected sequence; duplicate; older/reordered packet','0xFFFFFFFF to 0 wrap','Half-range ambiguity','Session change while messages are queued','Fresh packet after gap does not silently re-arm','Snapshot/configuration commit during recovery'],evidence:'Model comparison around wrap, state-transition coverage, no-order-while-unsynced assertion.',refs:['serial','mold']},
 {id:'D05',name:'quote_state.sv',language:'SystemVerilog',phase:'5-8',role:'Store bounded best-bid/ask snapshots and local freshness metadata.',contract:'Start with 64 explicit symbol slots and validate IDs before indexing. Record local receive time plus epoch. Updates commit atomically. Resolve same-address read/write with forwarding or a documented stall. This is a quote table, not an ITCH order book.',cases:['First update to invalid slot','Minimum/maximum/unmapped symbol','Consecutive same-symbol updates','Interleaved symbols and BRAM collision behavior','Reset/epoch rollover without leaking old state','Stale quote and locked/crossed/empty eligibility policies'],evidence:'Independent dictionary model, memory-hazard stress, epoch reset test.',refs:['itch','cdc']},
 {id:'D06',name:'decision_core.sv',language:'SystemVerilog',phase:'5-8',role:'Produce a candidate intent from eligible quote state.',contract:'Begin with spread and size thresholds in integer price units (1/10,000). Specify signedness, intermediate widths, rounding and saturation before optional Q-format multiplication. The rule is an engineering workload, not a profitability claim.',cases:['Threshold below/equal/above','Bid greater than ask before unsigned subtraction','Maximum 32-bit prices and quantities','Negative intermediate and sign extension','Multiplication overflow, saturation, rounding ties','Valid/data misalignment under pipeline bubbles'],evidence:'Exact integer reference, boundary sweep, bit-growth table, pipeline latency checks.',refs:['itch','ubsan']},
 {id:'D07',name:'risk_gate.sv',language:'SystemVerilog',phase:'9-12',role:'Admit only bounded, eligible intents and reserve exposure.',contract:'Require armed, healthy session, eligible fresh state, legal price/size, notional/position/rate capacity, and a free TX queue slot. Admit and reserve atomically. Include pending orders in exposure; use wide products and accumulators. Revalidate epoch/kill at final transmit admission.',cases:['Every limit at -1/equal/+1 relative to boundary','Two same-symbol orders exceed combined limit','Buy/sell pending exposure and both directional limits','Kill or config update while a candidate is stalled','No TX capacity; rate tokens exhausted','Quantity zero; maximum price*size; stale local age'],evidence:'Admission scoreboard, invariant proofs within declared bounds, all reject reasons covered.',refs:['formal','ubsan']},
 {id:'D08',name:'order_tracker.sv / feedback_decoder.sv',language:'SystemVerilog',phase:'9-12',role:'Track simulated pending, filled, rejected, and cancelled orders.',contract:'Use session epoch plus monotonically allocated ID. Unknown outcome holds reservation and disarms. A cancel request does not release exposure until confirmed. Deduplicate feedback. Only a trusted simulated-venue session may change execution state.',cases:['Duplicate ack/fill/cancel/reject','Partial fill followed by cancel acknowledgement','Fill racing cancel or kill','Unknown ID or old session feedback','Feedback quantity exceeds remaining quantity','Timeout, link loss, ID wrap and reset with outstanding orders'],evidence:'Lifecycle model and race tests; reconciliation trace; no double-release assertion.',refs:['ouch','soup']},
 {id:'D09',name:'order_encoder.sv / tx_scheduler.sv',language:'SystemVerilog',phase:'9-12 / 17-20',role:'Serialize OrderIntent-v1 and provide complete frames to the MAC.',contract:'Define every field, byte order, length, checksum, padding, and response port. Packetize before transmit if the MAC requires a continuous frame. Bound priority and queue depth. Kill suppresses queued unsent new orders; bytes already sent cannot be recalled.',cases:['Golden encoded packet and leading-zero fields','Final beat keep and minimum Ethernet padding','TX underflow and late backpressure','Kill before frame start versus after frame start','Queue overflow; feedback/control priority starvation','Reservation release only on known local failure, never ambiguous delivery'],evidence:'Independent C++ sink decode, egress byte comparison, transmit-admission properties.',refs:['pg210','udp']},
 {id:'D10',name:'eth_ipv4_udp_rx.sv',language:'SystemVerilog',phase:'13-16',role:'Filter and validate the declared Ethernet/IPv4/UDP subset.',contract:'Untagged Ethernet; IPv4 IHL=5; protocol 17; no fragmentation; configured addresses/ports; bounded total length. Verify IP and nonzero UDP checksums. Default project policy rejects omitted UDP checksum with a distinct counter. Ethernet padding is not UDP payload.',cases:['Bad FCS versus bad IPv4 header checksum versus bad UDP checksum','Zero UDP checksum and computed-zero checksum encoded 0xFFFF','Odd payload lengths and carry folding','IHL below 5/options; MF or nonzero fragment offset','Wrong destination/port/EtherType/version/protocol','UDP length <8, inconsistent IP length, truncation/oversize'],evidence:'Independently crafted packets, per-reason counters, every header field across beat boundaries.',refs:['udp','ipv4','pg210']},
 {id:'D11',name:'frame_commit.sv',language:'SystemVerilog',phase:'13-16',role:'Prevent late integrity errors from changing durable state.',contract:'A frame ID tags tentative data. Only complete, validated frames reach state/risk. For future multi-message datagrams, validate framing and all lengths before publishing any message; reserve descriptor capacity atomically. Aborts discard all tentative data.',cases:['Bad last byte/FCS after plausible first fields','Malformed later message in a datagram','Frame ID wrap and stale completion token','Abort followed immediately by a valid frame','Reset while integrity result is pending','Buffer exhaustion during tentative parse'],evidence:'No-state-write/no-order property before commit; rollback/abort regression.',refs:['pg210','mold','formal']},
 {id:'D12',name:'csr_axi_lite.sv / config_commit.sv',language:'SystemVerilog',phase:'9-12 / 21-26',role:'Expose versioned registers and atomic configuration.',contract:'32-bit data bus; define register addresses, byte strobes, reset values, read-only/error behavior, and one outstanding transaction initially. AW and W are independent. Write shadow limits, validate them, then commit a new epoch between admitted transactions.',cases:['AW before W, W before AW, together','BREADY/RREADY stalls and response stability','Partial WSTRB writes; misaligned/unmapped/read-only accesses','Reset between address, data, and response','Readback during atomic commit','Counter snapshot versus clear-on-write race'],evidence:'AXI-Lite protocol checker, host mock tests, coherent epoch readback.',refs:['tcl','cdc']},
 {id:'D13',name:'clock_reset_wrapper.sv / cdc_mailbox.sv',language:'SystemVerilog + XDC',phase:'17-20',role:'Manage actual clock boundaries and safe restart.',contract:'Use the selected MAC/GT clock topology. Equal nominal frequency does not imply related clocks. Use recognized CDC primitives or verified async FIFOs; synchronize reset release in each domain and wait for link/clock readiness. Keep control bundles coherent.',cases:['Different clock ratios and phases','Reset asserted in either domain mid-transfer','Stopped/restarted RX recovered clock','Mailbox update during previous acknowledgement','FIFO full at link loss','No output until all required readiness and epoch conditions hold'],evidence:'CDC structural review, clocks report, simulation stress, hardware reset traces. RTL tests do not prove analog metastability safety.',refs:['cdc','pg210']},
 {id:'D14',name:'latency_stats.sv / trace_buffer.sv',language:'SystemVerilog',phase:'17-32',role:'Correlate events and collect measurements without changing admission behavior.',contract:'Record SOP, end-of-frame/commit, decision, and transmit admission with packet ID and local timestamp. Counter snapshots cross domains coherently. Never subtract unrelated clock counters. Trace overflow drops debug records and increments a counter.',cases:['Timestamp wrap and long idle gaps','Counter snapshot while incrementing','Trace buffer full under burst','Rejected packet and no-decision paths','Multiple outstanding IDs','Instrumentation enabled/disabled timing comparison'],evidence:'Timestamp unit tests, trace-loss counters, calibrated boundary definitions.',refs:['benchmark','cdc']},
 {id:'D15',name:'kr260_top.sv / mac_phy_wrapper',language:'SystemVerilog + vendor IP',phase:'5-20',role:'Connect the portable core to actual GT, MAC, clocks, and board pins.',contract:'Reuse a selected MAC/PCS implementation and understand its interface. Freeze part, carrier revision, clocks, XDC, reset sequence, license, and tool versions. First demonstrate a single-port endpoint; do not infer a PCIe host interface from the SoC name.',cases:['Cold boot versus warm reset','Loss/recovery of block lock','Missing/incompatible cable or optics','MAC error indications and RX overrun','Continuous TX without underflow','Instrumentation and non-instrumented bitstream comparison'],evidence:'Baseline link/BIST logs, build manifest, ILA captures, peer counters.',refs:['kr260','kriaip','bist','license']},
 {id:'S01',name:'gen_packet.py / protocol.py / reference_model.py',language:'Python',phase:'1 onward',role:'Create exact bytes, model state, and generate expected outcomes.',contract:'Use bytes and structured packing with explicit network endianness. Reject invalid types including bool if integers are required. Preserve 64-bit values as integers or decimal strings in JSON consumers. Build at least one expected vector independently of the encoder.',cases:['0/max/-1/max+1 per field','Float/string/bool/None inputs','Exactly 31 bytes and 62 hex digits; leading zeros','Endian reversal and asymmetric test fields','Known hand-checked vector versus round-trip-only testing','Price scaling/rounding and sequence wrap'],evidence:'pytest boundary tests and deterministic fixture files; Python coverage reported separately.',refs:['itch','serial']},
 {id:'S02',name:'test_*.py / regression.py',language:'Python + cocotb',phase:'1 onward',role:'Drive DUT interfaces and score every accepted transaction.',contract:'Separate driver, monitor, model, scoreboard, and scenario coverage. Seed Python and simulator randomness; use timeouts and archive minimal failing input. Sample after settling. Every required test must execute; skip/xfail is not a pass.',cases:['All module cases plus pairwise fault combinations','Random valid traffic mixed with malicious lengths','Reset and stalls at each state transition','Repeated seeds reproduce failures','Missing output, duplicate output, wrong order','Mutated bug triggers the intended assertion/check'],evidence:'JUnit results, seed list, coverage ledger, regression manifest and failure waveforms.',refs:['cocotb','timingmodel','verilator']},
 {id:'S03',name:'codec.cpp / replay.cpp / venue_sim.cpp',language:'C++20',phase:'9 onward',role:'Replay market data and validate returned intents/feedback.',contract:'Use explicit byte reads or memcpy plus endian conversion; do not cast wire bytes into padded structs. Keep queues bounded and timeouts monotonic. Treat UDP sends as datagrams; TCP extensions must handle partial I/O. Host replay speed is measured, not assumed 10G.',cases:['Empty/truncated/oversized files and packets','Unaligned input; wrong endian; integer conversion','EINTR/EAGAIN, full socket queues and datagram errors','Malformed feedback/unknown IDs/duplicate fills','Shutdown with queued packets or incomplete logs','Bad PCAP link type/snaplen/timestamps and huge records'],evidence:'Golden vectors, CTest/unit tests, ASan/UBSan with failing exit status, fuzz corpus, measured offered load.',refs:['asan','ubsan','soup']},
 {id:'S04',name:'control.cpp / register_io.cpp',language:'C++20 (or a small C HAL)',phase:'17 onward',role:'Configure the onboard processor-to-PL control path.',contract:'Use a supported UIO/driver-backed mapping or platform API. volatile alone is not a memory-ordering strategy. Version the register map; validate input and read back the applied epoch. Keep control off the decision path; a host crash must disarm via watchdog.',cases:['Unsupported device ID or register version','Invalid address/alignment/range','Partially written shadow config and rejected commit','Readback mismatch; timeout; driver failure','Process crash and watchdog expiry','Counter snapshot and multiword value consistency'],evidence:'Mock register transport tests, hardware readback log, watchdog test.',refs:['imc','cdc']},
 {id:'S05',name:'build.tcl / reports.tcl / check_reports.py',language:'Tcl + Python',phase:'3 onward',role:'Reproduce the FPGA build and enforce evidence gates.',contract:'Resolve paths relative to the script, validate part/IP versions, read XDC, synthesize, implement, and collect structured timing/DRC/CDC/utilization data. A missing report or incomplete run fails. Clock constraints and timing exceptions require written justification.',cases:['Missing RTL/XDC/IP license','Wrong part and unmatched constraint object','Negative setup/hold slack; pulse-width violation','Unconstrained endpoints and unsafe CDC','Build failure cannot be hidden by a stale report','Paths with spaces and clean-checkout rebuild'],evidence:'Nonzero failure status, versioned manifest, post-route DCP and reports; no manual claims from source inspection.',refs:['tcl','features','cdc']},
 {id:'S06',name:'analyze_latency.py / evidence_manifest.py',language:'Python',phase:'27 onward',role:'Convert raw measurements into reproducible results.',contract:'Record units, endpoints, frequency, bitstream hash, traffic pattern, seed, sample count, warmup rule, instrument resolution, and loss. Treat missing events as missing data, not low latency. Keep integer timestamps until deliberate unit conversion.',cases:['Empty file and missing columns','Duplicate/missing/out-of-order packet IDs','Counter wrap and clock-domain mismatch','Outlier retained rather than silently trimmed','Invalid units and insufficient samples for tails','Trace overflow and generator shortfall'],evidence:'Small hand-calculated datasets, stable summaries, raw CSV + plots + assumptions.',refs:['benchmark']},
 {id:'X01',name:'moldudp64_rx.sv / itch_decoder.sv',language:'SystemVerilog (optional)',phase:'41-46',role:'Explore a real transport and a documented ITCH message subset.',contract:'Validate all message lengths/counts and session semantics. Unsupported messages are counted; messages needed to maintain selected state cannot be silently ignored. Complete order book work is a separate capacity, lifecycle, and recovery commitment.',cases:['Multiple messages per datagram across every byte lane','Count 0 heartbeat and 0xFFFF end-of-session','Truncated header/length field and inconsistent count','Per-message sequence increment; duplicates/gaps','Unknown types versus required book-changing types','Order table full/collision, missing delete target and replace lifecycle'],evidence:'Official-format synthetic fixtures plus licensed replay only where available; exact support matrix.',refs:['mold','itch']},
];

export const audit = [
 {title:'A parsed packet is not yet a validated packet',severity:'Design correction',detail:'Late FCS/checksum/length failure must suppress both state writes and order release. Baseline: buffer and validate complete frames. Optimize with tentative parsing only after proving the same commit rule.',refs:['pg210','udp']},
 {title:'One physical port changes the topology',severity:'Hardware gate',detail:'KR260 fits a single-port request/response endpoint: RX and TX share one full-duplex link. It does not supply separate 10G ingress/egress ports. PCIe/DMA host offload is outside the core.',refs:['kr260']},
 {title:'Free FPGA tools do not mean a free full Ethernet stack',severity:'Hardware gate',detail:'Resolve MAC versus PCS/PMA licensing and debug entitlement before buying. Candidate open implementations still need board integration, license review, and a pinned version.',refs:['license','features','taxi']},
 {title:'Snapshot quotes and ITCH need different state',severity:'Scope correction',detail:'Your 31-byte format contains a complete quote. ITCH describes order events. A parser-only ITCH extension cannot claim an accurate book without supported lifecycle messages, capacity behavior, and recovery.',refs:['itch','mold']},
 {title:'Backpressure cannot stop an incoming wire instantly',severity:'Design correction',detail:'A valid/ready core still needs finite buffering and whole-frame drop behavior at a non-throttleable RX boundary. Report capacity and the supported traffic envelope; no finite queue handles unlimited overload.',refs:['axis','pg210']},
 {title:'Bytes per second are not enough to prove line rate',severity:'Measurement gate',detail:'Define frame sizes, packet rate, messages per packet, accepted/rejected traffic, loss, and burst envelope. Check output expansion: one large response per tiny input can exceed TX capacity even when RX is 10G.',refs:['benchmark']},
 {title:'Risk must include orders still in flight',severity:'Design correction',detail:'Reserve pending exposure and a queue slot together. Handle duplicate acknowledgements, partial fills, cancel/fill races, unknown outcome, and session reset. A threshold comparator alone is not a complete risk gate.',refs:['ouch']},
 {title:'A gap counter does not repair state',severity:'Design correction',detail:'Disarm and invalidate affected state after a gap. Specify a coherent snapshot/restart flow and explicit re-arm. Check local age and epoch again at transmit admission.',refs:['serial','mold']},
 {title:'Minimize CDC after understanding the clocks',severity:'Design correction',detail:'The Reddit suggestion to avoid CDC is an optimization preference. RX, TX, and control may require crossings. Equal nominal frequency does not prove synchrony; use verified crossing structures and measure their cost.',refs:['cdc','pg210']},
 {title:'Simulator support is version-specific',severity:'Tool correction',detail:'cocotb drives a simulator; Verilator simulates portable RTL. Add a four-state lane and separate vendor-model tests. UVM support has recently expanded in Verilator but remains qualified.',refs:['cocotb','verilator','uvm','xsim']},
 {title:'A target clock is not a latency result',severity:'Measurement gate',detail:'156.25 MHz with 64 bits gives 10 Gb/s interface capacity. It does not prove useful payload throughput, zero loss, a 150 ns response, or timing closure. A universal 600 MHz target is unjustified for this project.',refs:['benchmark','tcl']},
 {title:'Coverage and proof claims need boundaries',severity:'Verification gate',detail:'Track scenarios, structural coverage, assertions, and software coverage separately. Test the checker by inserting a known fault. Record formal assumptions, bounds, and tool outcomes; neither simulation nor formal replaces board/CDC evidence.',refs:['formal','verilator']},
];

export const glossary = [
 ['RTL','Register-transfer level: describes registers and the logic that transforms data between clock edges.'],['MAC','Ethernet framing logic: frame boundaries, addressing, FCS, and the client data interface.'],['PCS/PMA','Physical coding and attachment functions that turn parallel Ethernet data into the encoded high-speed link.'],['GT / GTH','The FPGA high-speed serial transceiver hardware. It needs board-specific clocks and reset sequencing.'],['AXI-Stream','A stream of data beats with valid, optional ready, byte qualifiers, and packet boundary metadata.'],['Backpressure','A downstream block says it cannot accept more data yet. This requires a defined place for already-arriving data.'],['CDC','Clock-domain crossing: transferring data between clocks whose timing relationship requires special handling.'],['Latency / throughput','Latency is time for one item to traverse a path; throughput is the sustained processing rate. They are different.'],['Initiation interval','How often a pipeline can accept a new item. A four-cycle pipeline can still accept one item every cycle.'],['Scoreboard','Testbench logic that compares observed outputs and ordering with an independent expected model.'],['SVA / formal','Assertions specify properties. Formal tools search possible behaviors under declared assumptions; results have scope and bounds.'],['WNS / TNS','Worst negative slack and total negative slack summarize setup timing shortfalls. Also inspect hold, pulse width, and unconstrained paths.'],['ILA','Integrated Logic Analyzer: captures selected internal FPGA signals on hardware.'],['Epoch','A generation/session identifier that distinguishes current configuration and state from stale data.'],['Tick-to-trade','A domain name for the response path from a market-data event to an order. Its timing endpoints must be stated.'],['Q format','A binary fixed-point format with an explicitly defined number of fractional bits. It is different from decimal price scaling.'],
];
